def retry(times: int = 3, delay: float = 0.5):
    def decorator(fn):
        def wrapper(*args, **kwargs):
            last = None
            for _ in range(times):
                try:
                    return fn(*args, **kwargs)
                except Exception as exc:
                    last = exc
                    time.sleep(delay)
            raise last
        return wrapper
    return decorator

