def with_retries(attempts: int = 3, pause: float = 0.5):
    def decorator(func):
        def inner(*args, **kwargs):
            error = None
            for _ in range(attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    error = exc
                    time.sleep(pause)
            raise error
        return inner
    return decorator

