export function uniqueBy<T>(values: T[], key: (v: T) => string): T[] {
  const seen = new Map<string, T>();
  for (const value of values) {
    const k = key(value);
    if (!seen.has(k)) {
      seen.set(k, value);
    }
  }
  return Array.from(seen.values());
}

